import * as d3 from 'd3';
import {
  Sel, drawLabel, drawArrow, drawTensor, fmtNum,
} from '../primitives';
import { ComputationGraph } from '../../graph/types';
import { ComponentDef } from '../../components/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

export interface NormStep {
  id: number;
  label: string;
  shortLabel: string;
  formula: string;
  explanation: string;
  code: { title: string; lines: string[] };
  svgGroup: string;
  color: string;
  fill: string;
}

// ── Helpers ────────────────────────────────────────────────────────────────

function lbl(
  g: Gsel | Sel,
  x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; font?: string; anchor?: 'start' | 'middle' | 'end' } = {},
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel | Sel, x: number, y1: number, y2: number, color = '#78909c'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function arrowH(g: Gsel | Sel, x1: number, x2: number, y: number, color = '#78909c'): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

function makeLcg(seed: number) {
  let s = seed;
  return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 0xffffffff; };
}

function drawHeader(g: Gsel, cx: number, y: number, title: string, subtitle: string): number {
  lbl(g, cx, y, title, { size: 16, weight: '700' });
  y += 22;
  lbl(g, cx, y, subtitle, { size: 10, color: '#888' });
  return y + 40;
}

/** Draws a mini row vector (1 row × many cols) representing a [d_model] vector. */
function drawVector(
  g: Gsel, x: number, y: number, w: number, h: number,
  label: string, sublabel: string, fill: string, stroke: string,
  seed = 42,
): void {
  const lcg = makeLcg(seed);
  const cols = 12;
  const cellW = w / cols;
  const grp = g.append('g');
  for (let c = 0; c < cols; c++) {
    const v = 0.1 + lcg() * 0.6;
    grp.append('rect')
      .attr('x', x + c * cellW).attr('y', y)
      .attr('width', cellW - 0.5).attr('height', h)
      .attr('fill', d3.interpolate(fill, '#ffffff')(1 - v))
      .attr('stroke', stroke).attr('stroke-width', 0.4);
  }
  grp.append('rect').attr('x', x).attr('y', y).attr('width', w).attr('height', h)
    .attr('fill', 'none').attr('stroke', stroke).attr('stroke-width', 1.5).attr('rx', 2);
  lbl(grp as Sel, x + w / 2, y + h + 12, label, { size: 9, weight: '600', color: stroke });
  lbl(grp as Sel, x + w / 2, y + h + 24, sublabel, { size: 7, color: '#888', font: 'monospace' });
}

/** Draws a highlighted single row (one token's feature vector). */
function drawRowHighlight(
  g: Gsel, cx: number, y: number, w: number, h: number,
  fill: string, stroke: string, label: string, sublabel: string, seed = 99,
): { right: number; bottom: number } {
  const x = cx - w / 2;
  const lcg = makeLcg(seed);
  const cols = 14;
  const cellW = w / cols;
  const grp = g.append('g');
  for (let c = 0; c < cols; c++) {
    const v = 0.15 + lcg() * 0.6;
    grp.append('rect')
      .attr('x', x + c * cellW).attr('y', y)
      .attr('width', cellW - 0.5).attr('height', h)
      .attr('fill', d3.interpolate(fill, '#ffffff')(1 - v))
      .attr('stroke', '#e0e0e0').attr('stroke-width', 0.3);
  }
  grp.append('rect').attr('x', x).attr('y', y).attr('width', w).attr('height', h)
    .attr('fill', 'none').attr('stroke', stroke).attr('stroke-width', 2).attr('rx', 2);
  lbl(grp as Sel, cx, y + h + 13, label, { size: 9, weight: '600', color: stroke });
  lbl(grp as Sel, cx, y + h + 25, sublabel, { size: 7, color: '#888', font: 'monospace' });
  return { right: x + w, bottom: y + h };
}

/** Draws a scalar box. */
function drawScalar(
  g: Gsel, cx: number, y: number,
  value: string, label: string, fill: string, stroke: string,
): { bottom: number } {
  const w = 48, h = 32;
  const x = cx - w / 2;
  const grp = g.append('g');
  grp.append('rect').attr('x', x).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(grp as Sel, cx, y + h / 2, value, { size: 11, weight: '700', color: stroke });
  lbl(grp as Sel, cx, y + h + 13, label, { size: 8, color: '#666' });
  return { bottom: y + h };
}

/** Draws a formula step box (title + formula) centered at cx. */
function drawStepBlock(
  g: Gsel, cx: number, y: number, w: number,
  title: string, formula: string, fill: string, stroke: string, step: number,
): void {
  const x = cx - w / 2;
  const h = 42;
  g.append('rect').attr('x', x).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('rect').attr('x', x).attr('y', y).attr('width', 28).attr('height', h)
    .attr('rx', 6).attr('fill', stroke).attr('stroke', 'none');
  g.append('rect').attr('x', x + 22).attr('y', y).attr('width', 6).attr('height', h)
    .attr('fill', stroke).attr('stroke', 'none');
  lbl(g, x + 14, y + h / 2, String(step), { size: 11, weight: '700', color: '#fff' });
  lbl(g, cx + 14, y + h / 2 - 7, title, { size: 11, weight: '600', color: 'var(--text)', anchor: 'middle' });
  lbl(g, cx + 14, y + h / 2 + 9, formula, { size: 9, color: stroke, anchor: 'middle', font: 'monospace' });
}

/**
 * Draws a 3D isometric cuboid (N × S × D axes) with one or more colored slices
 * showing which dimension(s) are normalized together.
 *
 * variant:
 *   'layer'    — highlight one horizontal D-slice (per token, all features)
 *   'rms'      — same as layer
 *   'batch'    — highlight one vertical N-slice (all samples, per feature)
 *   'group'    — highlight G colored column groups within the D face
 *   'instance' — highlight one thin D-column per sample (per feature over seq)
 */
function drawNormOverviewCube(g: Gsel, cx: number, y: number, variant: string): number {
  // Isometric projection parameters
  const W = 100;  // width  (D axis, going right)
  const H = 60;   // height (S axis, going down)
  const D = 36;   // depth  (N axis, going upper-right)
  const dx = D * 0.6;  // x component of depth vector
  const dy = D * 0.4;  // y component of depth vector (negative = up)

  // Origin = front-bottom-left corner of the cube
  const ox = cx - W / 2;
  const oy = y + H + dy;  // shift down to make room for N-face on top

  // 8 corners (in 2D projected coords)
  // Front face (n=0): fl(ox,oy), fr(ox+W,oy), tr(ox+W,oy-H), tl(ox,oy-H)
  // Back face  (n=1): fl+(dx,−dy), fr+(dx,−dy), tr+(dx,−dy), tl+(dx,−dy)
  const fl  = [ox,        oy       ] as [number,number];
  const fr  = [ox + W,    oy       ] as [number,number];
  const tr  = [ox + W,    oy - H   ] as [number,number];
  const tl  = [ox,        oy - H   ] as [number,number];
  const bfl = [ox + dx,   oy - dy  ] as [number,number];
  const bfr = [ox+W+dx,   oy - dy  ] as [number,number];
  const btr = [ox+W+dx,   oy-H-dy  ] as [number,number];
  const btl = [ox+dx,     oy-H-dy  ] as [number,number];

  const poly = (pts: [number,number][], fill: string, stroke: string, sw = 1, opacity = 1) => {
    g.append('polygon')
      .attr('points', pts.map(p => p.join(',')).join(' '))
      .attr('fill', fill)
      .attr('stroke', stroke)
      .attr('stroke-width', sw)
      .attr('opacity', opacity);
  };

  // ── Base faces (dim faces of the cube) ──────────────────────────────────
  // Front face (D × S)
  poly([fl, fr, tr, tl], '#f8f8f8', '#bbb', 1);
  // Top face (D × N)
  poly([tl, tr, btr, btl], '#eeeeee', '#bbb', 1);
  // Right face (N × S)
  poly([fr, bfr, btr, tr], '#e8e8e8', '#bbb', 1);

  // ── Axis labels ─────────────────────────────────────────────────────────
  const lblOpts = { size: 8, color: '#666', weight: '600' };
  // D axis: bottom of front face, going right
  lbl(g, ox + W / 2, oy + 14, 'D (features)', lblOpts);
  // S axis: left of front face, going up
  lbl(g, ox - 34, oy - H / 2, 'S', { size: 8, color: '#666', weight: '600', anchor: 'middle' });
  lbl(g, ox - 24, oy - H / 2 + 10, '(seq)', { size: 7, color: '#999', anchor: 'middle' });
  // N axis: going upper-right from top-left
  lbl(g, ox + dx / 2 - 14, oy - H - dy / 2 - 6, 'N (batch)', { size: 8, color: '#666', weight: '600', anchor: 'middle' });

  // ── Highlighted slices per variant ──────────────────────────────────────
  if (variant === 'layer' || variant === 'rms') {
    // Highlight: one horizontal strip on front face = one token's D features
    // Strip at mid-height of front face
    const ht = H * 0.38;  // y offset from top of front face for the highlight strip
    const sh = H * 0.22;  // strip height
    const sColor = '#4ade80';
    const sStroke = '#16a34a';
    // Front strip
    const sfl: [number,number] = [ox,     oy - H + ht + sh];
    const sfr: [number,number] = [ox + W, oy - H + ht + sh];
    const str2: [number,number] = [ox + W, oy - H + ht];
    const stl2: [number,number] = [ox,     oy - H + ht];
    poly([sfl, sfr, str2, stl2], sColor, sStroke, 1.5, 0.55);
    // Top strip (same row projected on top face)
    const tsfl: [number,number] = [ox + dx,     oy - H - dy + ht + sh];
    const tsfr: [number,number] = [ox+W+dx,     oy - H - dy + ht + sh];
    const tstr: [number,number]  = [ox+W+dx,     oy - H - dy + ht];
    const tstl: [number,number]  = [ox + dx,     oy - H - dy + ht];
    poly([tsfl, tsfr, tstr, tstl], sColor, sStroke, 1.5, 0.35);

    const tag = variant === 'rms' ? 'per token, all D (no mean)' : 'per token, all D';
    lbl(g, cx + W / 2 + 26, oy - H + ht + sh / 2, tag, { size: 8, color: sStroke, weight: '600', anchor: 'start' });

  } else if (variant === 'batch') {
    // Highlight: one vertical slice on the right (N) face = all N for one (S,D) position
    const sd = W * 0.7; // x offset along D for the highlighted position
    // Front: vertical strip at sd
    const sw2 = W * 0.1;
    const sfl: [number,number] = [ox + sd,        oy       ];
    const sfr: [number,number] = [ox + sd + sw2,  oy       ];
    const str2: [number,number] = [ox + sd + sw2,  oy - H   ];
    const stl2: [number,number] = [ox + sd,        oy - H   ];
    poly([sfl, sfr, str2, stl2], '#fb923c', '#ea580c', 1.5, 0.55);
    // Top: project the strip onto top face
    const tsfl: [number,number] = [ox+sd+dx,       oy-H-dy  ];
    const tsfr: [number,number] = [ox+sd+sw2+dx,   oy-H-dy  ];
    const tstr: [number,number]  = [ox+sd+sw2,      oy-H     ];
    const tstl: [number,number]  = [ox+sd,          oy-H     ];
    poly([tsfl, tsfr, tstr, tstl], '#fb923c', '#ea580c', 1.5, 0.40);
    // Right face: full right N-face highlighted
    poly([fr, bfr, btr, tr], '#fb923c', '#ea580c', 1.5, 0.35);

    lbl(g, cx + W / 2 + 26, oy - H / 2, 'all N, per (S, D)', { size: 8, color: '#ea580c', weight: '600', anchor: 'start' });

  } else if (variant === 'group') {
    // Highlight: G groups as colored vertical bands along D axis
    const numGroups = 4; // display 4 groups for clarity
    const groupColors2 = ['#60a5fa', '#4ade80', '#f472b6', '#fb923c'];
    const groupStrokes2 = ['#2563eb', '#16a34a', '#db2777', '#ea580c'];
    const gw = W / numGroups;
    for (let gi = 0; gi < numGroups; gi++) {
      const gx0 = ox + gi * gw;
      // Front face band
      poly([
        [gx0, oy], [gx0 + gw, oy], [gx0 + gw, oy - H], [gx0, oy - H],
      ], groupColors2[gi], groupStrokes2[gi], 1.5, 0.45);
      // Top band
      poly([
        [gx0+dx, oy-H-dy], [gx0+gw+dx, oy-H-dy], [gx0+gw, oy-H], [gx0, oy-H],
      ], groupColors2[gi], groupStrokes2[gi], 1.5, 0.3);
      lbl(g, gx0 + gw / 2, oy + 14, `G${gi}`, { size: 7, color: groupStrokes2[gi], weight: '600' });
    }
    lbl(g, cx + W / 2 + 26, oy - H / 2, 'G groups along D', { size: 8, color: '#2563eb', weight: '600', anchor: 'start' });

  } else if (variant === 'instance') {
    // Highlight: one thin column band (one feature/channel) across all S rows
    const sw2 = W * 0.1;
    const sd = W * 0.55;
    // Front face: thin column
    poly([
      [ox + sd, oy], [ox + sd + sw2, oy], [ox + sd + sw2, oy - H], [ox + sd, oy - H],
    ], '#818cf8', '#4f46e5', 1.5, 0.55);
    // Right face: show multiple such columns (stacked along N)
    poly([fr, bfr, btr, tr], '#c7d2fe', '#4f46e5', 1.5, 0.25);
    // Back-projected strip on top
    poly([
      [ox+sd+dx, oy-H-dy], [ox+sd+sw2+dx, oy-H-dy], [ox+sd+sw2, oy-H], [ox+sd, oy-H],
    ], '#818cf8', '#4f46e5', 1.5, 0.35);
    lbl(g, cx + W / 2 + 26, oy - H / 2, 'per (N, D), over S', { size: 8, color: '#4f46e5', weight: '600', anchor: 'start' });
  }

  // ── Cube outline (redraw edges on top) ──────────────────────────────────
  const line = (a: [number,number], b: [number,number], color = '#999', sw2 = 1) =>
    g.append('line')
      .attr('x1', a[0]).attr('y1', a[1]).attr('x2', b[0]).attr('y2', b[1])
      .attr('stroke', color).attr('stroke-width', sw2);

  // Front face edges
  line(fl, fr); line(fr, tr); line(tr, tl); line(tl, fl);
  // Back face edges (dashed for hidden)
  [[bfl, bfr], [bfr, btr], [btr, btl], [btl, bfl]].forEach(([a, b]) =>
    g.append('line')
      .attr('x1', (a as [number,number])[0]).attr('y1', (a as [number,number])[1])
      .attr('x2', (b as [number,number])[0]).attr('y2', (b as [number,number])[1])
      .attr('stroke', '#bbb').attr('stroke-width', 0.8).attr('stroke-dasharray', '3,2'),
  );
  // Connecting edges (front to back)
  line(fl, bfl, '#bbb', 0.8); line(fr, bfr); line(tr, btr); line(tl, btl, '#bbb', 0.8);

  return oy + 28; // return y below the cube
}

// ── LayerNorm ──────────────────────────────────────────────────────────────

function renderLayerNorm(
  g: Gsel, seqLen: number, dModel: number, W: number,
): { width: number; height: number; steps: NormStep[] } {
  const cx = W / 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'LayerNorm', `d_model=${dModel}  seq_len=${seqLen}  params: 2×d_model (γ + β)`);
  y = drawNormOverviewCube(g, cx, y, 'layer');
  y += 16;

  // Input
  const s0 = g.append('g').attr('class', 'step-node step-norm-input').attr('data-step', '0');
  drawTensor(s0 as Sel, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#e8f5e9', '#2e7d32');
  y += 52;

  // Step 1: per-token row
  const s1 = g.append('g').attr('class', 'step-node step-norm-row').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s1, cx, y, 320, 'Select token row xₜ', 'xₜ = x[t, :] ∈ ℝ^d_model', '#e8f5e9', '#2e7d32', 1);
  y += 58;
  const row1 = drawRowHighlight(s1, cx, y, 280, 16, '#e8f5e9', '#2e7d32', 'xₜ  (one token)', `[d_model=${dModel}]`, 7);
  y = row1.bottom + 36;

  // Step 2: compute mean
  const s2 = g.append('g').attr('class', 'step-node step-norm-mean').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s2, cx, y, 320, 'Compute mean μ', 'μ = (1/d) Σᵢ xᵢ', '#fff3e0', '#e65100', 2);
  y += 58;

  // Show: row → sum → divide → μ scalar
  const rowX2 = cx - 180;
  drawRowHighlight(s2, rowX2 + 70, y, 140, 14, '#e8f5e9', '#2e7d32', 'xₜ', `[${dModel}]`, 8);
  arrowH(s2, rowX2 + 148, rowX2 + 172, y + 7, '#e65100');
  lbl(s2, rowX2 + 160, y - 4, 'Σ/d', { size: 9, weight: '700', color: '#e65100' });
  drawScalar(s2, cx + 80, y - 8, 'μ', 'scalar', '#fff3e0', '#e65100');
  lbl(s2, cx, y + 32, `μ = mean over all ${dModel} features of token t`, { size: 8, color: '#666' });
  y += 60;

  // Step 3: variance
  const s3 = g.append('g').attr('class', 'step-node step-norm-var').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s3, cx, y, 320, 'Compute variance σ²', 'σ² = mean((xᵢ − μ)²) + ε', '#fce4ec', '#c62828', 3);
  y += 58;

  // Visual: (x - μ)² → mean
  const vx = cx - 200;
  drawRowHighlight(s3, vx + 70, y, 100, 14, '#e8f5e9', '#2e7d32', 'xₜ', `[${dModel}]`, 9);
  arrowH(s3, vx + 128, vx + 148, y + 7, '#c62828');
  lbl(s3, vx + 138, y - 4, '−μ', { size: 9, weight: '700', color: '#c62828' });
  drawRowHighlight(s3, vx + 155, y, 80, 14, '#fce4ec', '#c62828', '(x−μ)', `[${dModel}]`, 11);
  arrowH(s3, vx + 243, vx + 263, y + 7, '#c62828');
  lbl(s3, vx + 253, y - 4, '²', { size: 11, weight: '700', color: '#c62828' });
  drawRowHighlight(s3, vx + 270, y, 80, 14, '#fce4ec', '#c62828', '(x−μ)²', `[${dModel}]`, 13);
  arrowH(s3, vx + 358, vx + 378, y + 7, '#c62828');
  lbl(s3, vx + 368, y - 4, 'mean', { size: 8, weight: '700', color: '#c62828' });
  drawScalar(s3, vx + 415, y - 8, 'σ²', 'scalar', '#fce4ec', '#c62828');
  lbl(s3, cx, y + 32, `ε=${1e-6} added for numerical stability`, { size: 8, color: '#888' });
  y += 58;

  // Step 4: normalize
  const s4 = g.append('g').attr('class', 'step-node step-norm-normalize').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s4, cx, y, 320, 'Normalize x̂', 'x̂ = (x − μ) / √(σ² + ε)', '#e3f2fd', '#1565c0', 4);
  y += 58;
  drawRowHighlight(s4, cx, y, 280, 16, '#e3f2fd', '#1565c0', 'x̂ₜ  (zero mean, unit variance)', `[d_model=${dModel}]`, 15);
  y += 16 + 36;

  // Step 5: scale + shift
  const s5 = g.append('g').attr('class', 'step-node step-norm-scale').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s5, cx, y, 320, 'Scale + Shift', 'out = γ ⊙ x̂ + β', '#f3e5f5', '#6a1b9a', 5);
  y += 58;

  const vecW = 200, vecH = 20;
  const vecX = cx - vecW / 2;
  drawRowHighlight(s5, cx, y, vecW, 14, '#e3f2fd', '#1565c0', 'x̂ₜ', `[${dModel}]`, 17);
  y += 14 + 32;
  lbl(s5, cx - vecW / 2 - 14, y + vecH / 2, '×', { size: 14, weight: '700', color: '#6a1b9a' });
  drawVector(s5, vecX, y, vecW, vecH, 'γ  (scale)', `[d_model=${dModel}]`, '#f3e5f5', '#6a1b9a', 21);
  y += vecH + 38;
  lbl(s5, cx - vecW / 2 - 14, y + vecH / 2, '+', { size: 14, weight: '700', color: '#ad1457' });
  drawVector(s5, vecX, y, vecW, vecH, 'β  (shift)', `[d_model=${dModel}]`, '#fce4ec', '#ad1457', 23);
  y += vecH + 38;
  arrowDown(g, cx, y - 10, y + 2);
  drawTensor(s5 as Sel, cx - 110, y + 4, 220, 30, `out: [batch, ${seqLen}, ${dModel}]`, '#f3e5f5', '#6a1b9a');
  y += 52;

  lbl(g, cx, y, `Params: ${fmtNum(2 * dModel)} (γ + β, each [${dModel}])  |  Cost: O(seq × d_model)`, { size: 10, color: '#2563eb', weight: '600' });
  y += 24;

  const steps: NormStep[] = [
    { id: 1, label: 'Select Token Row', shortLabel: 'Row xₜ',
      formula: 'xₜ = x[t, :] ∈ ℝ^d_model',
      explanation: `LayerNorm operates independently on each token's feature vector. For token t, we take xₜ of shape [${dModel}].`,
      code: { title: 'Token row', lines: [`# x: [batch, seq_len, ${dModel}]`, 'x_t = x[:, t, :]  # shape [batch, d_model]'] },
      svgGroup: 'step-norm-row', color: '#2e7d32', fill: '#e8f5e9' },
    { id: 2, label: 'Compute Mean μ', shortLabel: 'Mean μ',
      formula: 'μ = (1/d) Σᵢ xᵢ',
      explanation: `Mean is computed over all ${dModel} features of one token. This "centers" the distribution to zero mean.`,
      code: { title: 'Mean', lines: ['mu = x.mean(dim=-1, keepdim=True)  # [batch, seq, 1]'] },
      svgGroup: 'step-norm-mean', color: '#e65100', fill: '#fff3e0' },
    { id: 3, label: 'Compute Variance σ²', shortLabel: 'Variance',
      formula: 'σ² = mean((x − μ)²) + ε',
      explanation: `Variance measures the spread. Adding ε (${1e-6}) prevents division by zero when the activations are all identical.`,
      code: { title: 'Variance', lines: ['var = ((x - mu) ** 2).mean(dim=-1, keepdim=True)'] },
      svgGroup: 'step-norm-var', color: '#c62828', fill: '#fce4ec' },
    { id: 4, label: 'Normalize x̂', shortLabel: 'Normalize',
      formula: 'x̂ = (x − μ) / √(σ² + ε)',
      explanation: `After normalization, x̂ has zero mean and unit variance across the ${dModel} features, stabilizing the gradient flow.`,
      code: { title: 'Normalize', lines: ['x_hat = (x - mu) / torch.sqrt(var + 1e-6)'] },
      svgGroup: 'step-norm-normalize', color: '#1565c0', fill: '#e3f2fd' },
    { id: 5, label: 'Scale + Shift', shortLabel: 'γ, β',
      formula: 'out = γ ⊙ x̂ + β',
      explanation: `Learnable γ (scale) and β (shift) restore the model's expressiveness. Both are [${dModel}] vectors, totaling ${fmtNum(2 * dModel)} parameters.`,
      code: { title: 'Scale+Shift', lines: ['# gamma, beta: learned [d_model] params', 'out = self.gamma * x_hat + self.beta'] },
      svgGroup: 'step-norm-scale', color: '#6a1b9a', fill: '#f3e5f5' },
  ];

  return { width: W, height: y + 20, steps };
}

// ── RMSNorm ────────────────────────────────────────────────────────────────

function renderRMSNorm(
  g: Gsel, seqLen: number, dModel: number, W: number,
): { width: number; height: number; steps: NormStep[] } {
  const cx = W / 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'RMSNorm', `d_model=${dModel}  seq_len=${seqLen}  params: d_model (γ only, no β)`);
  y = drawNormOverviewCube(g, cx, y, 'rms');
  y += 16;

  // Input
  const s0 = g.append('g').attr('class', 'step-node step-norm-input').attr('data-step', '0');
  drawTensor(s0 as Sel, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#e3f2fd', '#1565c0');
  y += 52;

  // Step 1: square
  const s1 = g.append('g').attr('class', 'step-node step-norm-sq').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s1, cx, y, 320, 'Square each element', 'x² = xᵢ ⊙ xᵢ', '#e3f2fd', '#1565c0', 1);
  y += 58;

  const row1 = drawRowHighlight(s1, cx - 80, y, 130, 14, '#e3f2fd', '#1565c0', 'xₜ', `[${dModel}]`, 7);
  arrowH(s1, cx - 80 + 138, cx - 80 + 160, y + 7, '#1565c0');
  lbl(s1, cx - 80 + 149, y - 4, '²', { size: 12, weight: '700', color: '#1565c0' });
  drawRowHighlight(s1, cx + 90, y, 130, 14, '#bbdefb', '#1565c0', 'xₜ²', `[${dModel}]`, 9);
  y = row1.bottom + 36;

  // Step 2: mean of squares → RMS
  const s2 = g.append('g').attr('class', 'step-node step-norm-rms').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s2, cx, y, 320, 'Compute RMS', 'RMS = √(mean(x²) + ε)', '#fff3e0', '#e65100', 2);
  y += 58;

  drawRowHighlight(s2, cx - 130, y, 100, 14, '#bbdefb', '#1565c0', 'xₜ²', `[${dModel}]`, 10);
  arrowH(s2, cx - 22, cx + 2, y + 7, '#e65100');
  lbl(s2, cx - 10, y - 4, 'mean', { size: 8, weight: '700', color: '#e65100' });
  drawScalar(s2, cx + 50, y - 8, 'ms', 'mean sq.', '#fff3e0', '#e65100');
  arrowH(s2, cx + 76, cx + 100, y + 7, '#e65100');
  lbl(s2, cx + 88, y - 4, '√(·+ε)', { size: 8, weight: '700', color: '#e65100' });
  drawScalar(s2, cx + 148, y - 8, 'RMS', 'scalar', '#fff3e0', '#e65100');
  lbl(s2, cx, y + 32, 'No mean-centering — RMSNorm only measures scale, not shift', { size: 8, color: '#888' });
  y += 60;

  // Step 3: normalize
  const s3 = g.append('g').attr('class', 'step-node step-norm-normalize').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s3, cx, y, 320, 'Normalize', 'x̂ = x / RMS(x)', '#dcfce7', '#166534', 3);
  y += 58;

  drawRowHighlight(s3, cx - 130, y, 100, 14, '#e3f2fd', '#1565c0', 'xₜ', `[${dModel}]`, 11);
  arrowH(s3, cx - 22, cx + 2, y + 7, '#166534');
  lbl(s3, cx - 10, y - 4, '÷RMS', { size: 9, weight: '700', color: '#166534' });
  drawRowHighlight(s3, cx + 20, y, 120, 14, '#dcfce7', '#166534', 'x̂ₜ  (RMS-normalized)', `[${dModel}]`, 13);
  y += 14 + 36;

  // Annotation: vs LayerNorm
  const annBox = g.append('g');
  annBox.append('rect').attr('x', cx - 200).attr('y', y).attr('width', 400).attr('height', 36)
    .attr('rx', 6).attr('fill', '#fffbeb').attr('stroke', '#f59e0b').attr('stroke-width', 1).attr('stroke-dasharray', '4,3');
  lbl(annBox as Sel, cx, y + 12, 'vs LayerNorm: no mean subtraction step  →  fewer ops, same stabilization effect', { size: 8, color: '#92400e' });
  lbl(annBox as Sel, cx, y + 26, 'Used by: Llama, Gemma, Mistral, Qwen, DeepSeek', { size: 8, color: '#92400e', weight: '600' });
  y += 52;

  // Step 4: scale only
  const s4 = g.append('g').attr('class', 'step-node step-norm-scale').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s4, cx, y, 320, 'Scale (no shift)', 'out = γ ⊙ x̂', '#f3e5f5', '#6a1b9a', 4);
  y += 58;

  const vecW = 200, vecH = 20;
  drawRowHighlight(s4, cx, y, vecW, 14, '#dcfce7', '#166534', 'x̂ₜ', `[${dModel}]`, 15);
  y += 14 + 32;
  lbl(s4, cx - vecW / 2 - 14, y + vecH / 2, '×', { size: 14, weight: '700', color: '#6a1b9a' });
  drawVector(s4, cx - vecW / 2, y, vecW, vecH, 'γ  (scale only — no β)', `[d_model=${dModel}]`, '#f3e5f5', '#6a1b9a', 21);
  y += vecH + 38;
  arrowDown(g, cx, y - 10, y + 2);
  drawTensor(s4 as Sel, cx - 110, y + 4, 220, 30, `out: [batch, ${seqLen}, ${dModel}]`, '#f3e5f5', '#6a1b9a');
  y += 52;

  lbl(g, cx, y, `Params: ${fmtNum(dModel)} (γ only)  |  ~33% fewer params than LayerNorm  |  Cost: O(seq × d_model)`, { size: 10, color: '#2563eb', weight: '600' });
  y += 24;

  const steps: NormStep[] = [
    { id: 1, label: 'Square Elements', shortLabel: 'x²',
      formula: 'x² = xᵢ ⊙ xᵢ',
      explanation: `Square every element of the token vector xₜ. This is used to measure the "energy" (scale) of the activations, without caring about the mean.`,
      code: { title: 'Square', lines: ['x_sq = x ** 2  # element-wise square'] },
      svgGroup: 'step-norm-sq', color: '#1565c0', fill: '#e3f2fd' },
    { id: 2, label: 'Compute RMS', shortLabel: 'RMS',
      formula: 'RMS = √(mean(x²) + ε)',
      explanation: `Take the mean of the squared values, add ε for stability, then take the square root. This gives the root-mean-square — a measure of the activation magnitude.`,
      code: { title: 'RMS', lines: ['rms = x.pow(2).mean(-1, keepdim=True).add(1e-6).rsqrt()'] },
      svgGroup: 'step-norm-rms', color: '#e65100', fill: '#fff3e0' },
    { id: 3, label: 'Normalize by RMS', shortLabel: 'Normalize',
      formula: 'x̂ = x / RMS(x)',
      explanation: `Divide each element by the RMS. Unlike LayerNorm, there is NO mean subtraction — RMSNorm assumes activations are already approximately zero-mean, which holds in practice.`,
      code: { title: 'Normalize', lines: ['x_hat = x * rms  # rms is already reciprocal (rsqrt)'] },
      svgGroup: 'step-norm-normalize', color: '#166534', fill: '#dcfce7' },
    { id: 4, label: 'Scale γ (no shift)', shortLabel: 'Scale γ',
      formula: 'out = γ ⊙ x̂',
      explanation: `Only a learnable scale γ [${dModel}] is applied — no bias β. This reduces parameters from ${fmtNum(2 * dModel)} to ${fmtNum(dModel)} while maintaining full expressiveness.`,
      code: { title: 'Scale', lines: ['# self.gamma = nn.Parameter(torch.ones(d_model))', 'return self.gamma * x_hat'] },
      svgGroup: 'step-norm-scale', color: '#6a1b9a', fill: '#f3e5f5' },
  ];

  return { width: W, height: y + 20, steps };
}

// ── BatchNorm ──────────────────────────────────────────────────────────────

function renderBatchNorm(
  g: Gsel, seqLen: number, dModel: number, W: number,
): { width: number; height: number; steps: NormStep[] } {
  const cx = W / 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'BatchNorm', `d_model=${dModel}  seq_len=${seqLen}  normalizes over batch dimension`);
  y = drawNormOverviewCube(g, cx, y, 'batch');
  y += 16;

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#fff3e0', '#e65100');
  y += 52;

  // Axis diagram: show what BatchNorm normalizes over
  const s0 = g.append('g').attr('class', 'step-node step-norm-input').attr('data-step', '0');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s0, cx, y, 340, 'Normalization axis: over Batch', 'μ_c = E_batch[x], σ²_c = Var_batch[x]', '#fff3e0', '#e65100', 1);
  y += 58;

  // Draw a 3-column "batch stack" illustration
  const batchN = 3, colW = 50, colH = 60, gap = 18;
  const stackX = cx - (batchN * (colW + gap)) / 2;
  const colors = ['#fff3e0', '#e3f2fd', '#f3e5f5'];
  const strokes = ['#e65100', '#1565c0', '#6a1b9a'];
  for (let b = 0; b < batchN; b++) {
    const bx = stackX + b * (colW + gap);
    s0.append('rect').attr('x', bx).attr('y', y).attr('width', colW).attr('height', colH)
      .attr('rx', 4).attr('fill', colors[b]).attr('stroke', strokes[b]).attr('stroke-width', 1.5);
    lbl(s0, bx + colW / 2, y + colH / 2, `B${b}`, { size: 10, weight: '700', color: strokes[b] });
  }
  // arrow showing "normalize over this direction"
  const arrowY = y + colH + 16;
  s0.append('line')
    .attr('x1', stackX - 8).attr('y1', arrowY)
    .attr('x2', stackX + batchN * (colW + gap) - gap + 8).attr('y2', arrowY)
    .attr('stroke', '#e65100').attr('stroke-width', 2).attr('marker-end', 'none');
  s0.append('text').attr('x', stackX + batchN * (colW + gap) / 2).attr('y', arrowY + 14)
    .attr('text-anchor', 'middle').attr('font-size', '9px').attr('fill', '#e65100').attr('font-weight', '600')
    .text('← normalize over B samples for each (pos, feature) →');
  lbl(s0, cx, arrowY + 28, 'Each feature at each seq position gets its own μ, σ across the batch', { size: 8, color: '#888' });
  y += colH + 54;

  // Step 2: compute batch stats
  const s2 = g.append('g').attr('class', 'step-node step-norm-mean').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s2, cx, y, 320, 'Batch μ and σ²', 'μ_c = mean_B(x_c),  σ²_c = var_B(x_c)', '#e8f5e9', '#2e7d32', 2);
  y += 58;

  const statW = 120, statH = 18;
  drawVector(s2, cx - statW - 20, y, statW, statH, 'μ  per (pos, feature)', `[${seqLen}, ${dModel}]`, '#e8f5e9', '#2e7d32', 31);
  drawVector(s2, cx + 20, y, statW, statH, 'σ²  per (pos, feature)', `[${seqLen}, ${dModel}]`, '#fff3e0', '#e65100', 33);
  lbl(s2, cx, y + statH + 42, `computed across B training samples — unstable for B=1`, { size: 8, color: '#888' });
  y += statH + 64;

  // Step 3: normalize
  const s3 = g.append('g').attr('class', 'step-node step-norm-normalize').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s3, cx, y, 320, 'Normalize', 'x̂ = (x − μ_c) / √(σ²_c + ε)', '#e3f2fd', '#1565c0', 3);
  y += 58;
  drawRowHighlight(s3, cx, y, 280, 16, '#e3f2fd', '#1565c0', 'x̂  (batch-normalized)', `[batch, ${seqLen}, ${dModel}]`, 35);
  y += 16 + 36;

  // Step 4: scale + shift
  const s4 = g.append('g').attr('class', 'step-node step-norm-scale').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s4, cx, y, 320, 'Scale + Shift', 'out = γ ⊙ x̂ + β', '#f3e5f5', '#6a1b9a', 4);
  y += 58;

  const vW = 200, vH = 20;
  lbl(s4, cx - vW / 2 - 14, y + vH / 2, '×', { size: 14, weight: '700', color: '#6a1b9a' });
  drawVector(s4, cx - vW / 2, y, vW, vH, 'γ', `[${dModel}]`, '#f3e5f5', '#6a1b9a', 41);
  y += vH + 38;
  lbl(s4, cx - vW / 2 - 14, y + vH / 2, '+', { size: 14, weight: '700', color: '#ad1457' });
  drawVector(s4, cx - vW / 2, y, vW, vH, 'β', `[${dModel}]`, '#fce4ec', '#ad1457', 43);
  y += vH + 38;
  arrowDown(g, cx, y - 10, y + 2);
  drawTensor(s4 as Sel, cx - 110, y + 4, 220, 30, `out: [batch, ${seqLen}, ${dModel}]`, '#f3e5f5', '#6a1b9a');
  y += 52;

  // Warning box
  const warnBox = g.append('g');
  warnBox.append('rect').attr('x', cx - 200).attr('y', y).attr('width', 400).attr('height', 36)
    .attr('rx', 6).attr('fill', '#fff7ed').attr('stroke', '#f97316').attr('stroke-width', 1.5);
  lbl(warnBox as Sel, cx, y + 12, '⚠  Requires batch statistics at inference — use running mean/var', { size: 8, color: '#9a3412', weight: '600' });
  lbl(warnBox as Sel, cx, y + 26, 'Not ideal for NLP (variable-length sequences, small batches) — prefer LayerNorm', { size: 8, color: '#9a3412' });
  y += 52;

  lbl(g, cx, y, `Params: ${fmtNum(2 * dModel)} (γ + β)  |  Cost: O(batch × seq × d_model)`, { size: 10, color: '#2563eb', weight: '600' });
  y += 24;

  const steps: NormStep[] = [
    { id: 1, label: 'Batch Axis Normalization', shortLabel: 'Batch Axis',
      formula: 'norm over B samples per (pos, feat)',
      explanation: `BatchNorm normalizes over the batch dimension B. For each (sequence position, feature), it computes statistics across all B training samples — unlike LayerNorm which normalizes per token.`,
      code: { title: 'BatchNorm axis', lines: ['# x: [B, seq, d_model]', '# BN normalizes over B (dim=0) for each (seq pos, feature)', 'bn = nn.BatchNorm1d(d_model)'] },
      svgGroup: 'step-norm-input', color: '#e65100', fill: '#fff3e0' },
    { id: 2, label: 'Compute Batch μ, σ²', shortLabel: 'Batch Stats',
      formula: 'μ_c = E_B[x_c], σ²_c = Var_B[x_c]',
      explanation: `Compute mean and variance per feature across the batch. These are running statistics (exponential moving average) tracked during training for use at inference time.`,
      code: { title: 'Stats', lines: ['mu = x.mean(dim=0)   # [seq, d_model]', 'var = x.var(dim=0)    # [seq, d_model]'] },
      svgGroup: 'step-norm-mean', color: '#2e7d32', fill: '#e8f5e9' },
    { id: 3, label: 'Normalize', shortLabel: 'Normalize',
      formula: 'x̂ = (x − μ_c) / √(σ²_c + ε)',
      explanation: `Normalize using the batch statistics. The output has zero mean and unit variance across the batch for each feature.`,
      code: { title: 'Normalize', lines: ['x_hat = (x - mu) / torch.sqrt(var + 1e-5)'] },
      svgGroup: 'step-norm-normalize', color: '#1565c0', fill: '#e3f2fd' },
    { id: 4, label: 'Scale + Shift', shortLabel: 'γ, β',
      formula: 'out = γ ⊙ x̂ + β',
      explanation: `Learnable γ and β restore expressiveness. ${fmtNum(2 * dModel)} parameters total. BatchNorm is common in CNNs but problematic in NLP due to variable-length sequences and small batch sizes.`,
      code: { title: 'Scale+Shift', lines: ['out = gamma * x_hat + beta'] },
      svgGroup: 'step-norm-scale', color: '#6a1b9a', fill: '#f3e5f5' },
  ];

  return { width: W, height: y + 20, steps };
}

// ── GroupNorm ──────────────────────────────────────────────────────────────

function renderGroupNorm(
  g: Gsel, seqLen: number, dModel: number, W: number,
): { width: number; height: number; steps: NormStep[] } {
  const cx = W / 2;
  let y = 28;
  const G = 32; // number of groups
  const groupSize = dModel / G;

  y = drawHeader(g, cx, y, 'GroupNorm', `d_model=${dModel}  G=${G} groups  group_size=${groupSize}  seq_len=${seqLen}`);
  y = drawNormOverviewCube(g, cx, y, 'group');
  y += 16;

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#e8f5e9', '#2e7d32');
  y += 52;

  // Step 1: reshape into groups
  const s1 = g.append('g').attr('class', 'step-node step-norm-reshape').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s1, cx, y, 340, 'Reshape into G groups', `x → [batch, ${seqLen}, G=${G}, d/G=${groupSize}]`, '#e8f5e9', '#2e7d32', 1);
  y += 58;

  // Show groups as colored column segments
  const gDisplay = Math.min(G, 8);
  const gW = 280;
  const segW = gW / gDisplay;
  const segH = 36;
  const gX = cx - gW / 2;
  const groupColors = ['#bbdefb', '#c8e6c9', '#fce4ec', '#fff3e0', '#e8eaf6', '#f3e5f5', '#e0f2f1', '#fff8e1'];
  const groupStrokes = ['#1565c0', '#2e7d32', '#ad1457', '#e65100', '#3949ab', '#6a1b9a', '#00695c', '#f9a825'];
  for (let gi = 0; gi < gDisplay; gi++) {
    const lcg = makeLcg(gi * 17 + 3);
    for (let ci = 0; ci < 3; ci++) {
      const v = 0.2 + lcg() * 0.5;
      s1.append('rect')
        .attr('x', gX + gi * segW + ci * (segW / 3)).attr('y', y)
        .attr('width', segW / 3 - 0.5).attr('height', segH)
        .attr('fill', d3.interpolate(groupColors[gi % 8], '#ffffff')(1 - v))
        .attr('stroke', '#e0e0e0').attr('stroke-width', 0.3);
    }
    s1.append('rect').attr('x', gX + gi * segW).attr('y', y)
      .attr('width', segW).attr('height', segH)
      .attr('fill', 'none').attr('stroke', groupStrokes[gi % 8]).attr('stroke-width', 1.5).attr('rx', 2);
    lbl(s1, gX + gi * segW + segW / 2, y + segH + 12, `G${gi}`, { size: 7, color: groupStrokes[gi % 8], weight: '600' });
  }
  if (G > gDisplay) {
    lbl(s1, cx, y + segH + 24, `... ${G - gDisplay} more groups`, { size: 7, color: '#888' });
  }
  lbl(s1, cx, y - 8, `Each group = ${groupSize} features  (G=${G} groups total)`, { size: 8, color: '#666' });
  y += segH + 42;

  // Step 2: per-group stats
  const s2 = g.append('g').attr('class', 'step-node step-norm-mean').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s2, cx, y, 340, 'Per-group μ and σ²', 'μ_g = mean(x_g),  σ²_g = var(x_g)', '#fff3e0', '#e65100', 2);
  y += 58;

  // Show one group with its μ/σ
  const sg = s2.append('g');
  const sgX = cx - 140;
  sg.append('rect').attr('x', sgX).attr('y', y).attr('width', 80).attr('height', 30)
    .attr('rx', 4).attr('fill', '#c8e6c9').attr('stroke', '#2e7d32').attr('stroke-width', 1.5);
  lbl(sg as Sel, sgX + 40, y + 15, 'Group g', { size: 9, weight: '600', color: '#2e7d32' });
  arrowH(sg as Sel, sgX + 88, sgX + 112, y + 15, '#e65100');
  drawScalar(sg as Sel, sgX + 160, y - 1, 'μ_g', 'mean', '#fff3e0', '#e65100');
  drawScalar(sg as Sel, sgX + 220, y - 1, 'σ²_g', 'var', '#fce4ec', '#c62828');
  lbl(sg as Sel, cx, y + 46, `Each of the ${G} groups computes its own statistics independently`, { size: 8, color: '#666' });
  y += 72;

  // Step 3: normalize within group
  const s3 = g.append('g').attr('class', 'step-node step-norm-normalize').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s3, cx, y, 340, 'Normalize within each group', 'x̂_g = (x_g − μ_g) / √(σ²_g + ε)', '#e3f2fd', '#1565c0', 3);
  y += 58;
  drawRowHighlight(s3, cx, y, 280, 16, '#e3f2fd', '#1565c0', 'x̂  (group-normalized)', `[batch, ${seqLen}, ${dModel}]`, 37);
  y += 16 + 36;

  // Step 4: scale + shift + reshape back
  const s4 = g.append('g').attr('class', 'step-node step-norm-scale').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s4, cx, y, 340, 'Scale + Shift + Reshape back', 'out = γ ⊙ x̂ + β,  reshape → [b, seq, d]', '#f3e5f5', '#6a1b9a', 4);
  y += 58;

  const vW = 200, vH = 20;
  lbl(s4, cx - vW / 2 - 14, y + vH / 2, '×', { size: 14, weight: '700', color: '#6a1b9a' });
  drawVector(s4, cx - vW / 2, y, vW, vH, 'γ', `[d_model=${dModel}]`, '#f3e5f5', '#6a1b9a', 51);
  y += vH + 38;
  lbl(s4, cx - vW / 2 - 14, y + vH / 2, '+', { size: 14, weight: '700', color: '#ad1457' });
  drawVector(s4, cx - vW / 2, y, vW, vH, 'β', `[d_model=${dModel}]`, '#fce4ec', '#ad1457', 53);
  y += vH + 38;
  arrowDown(g, cx, y - 10, y + 2);
  drawTensor(s4 as Sel, cx - 110, y + 4, 220, 30, `out: [batch, ${seqLen}, ${dModel}]`, '#f3e5f5', '#6a1b9a');
  y += 52;

  // Comparison note
  const cBox = g.append('g');
  cBox.append('rect').attr('x', cx - 200).attr('y', y).attr('width', 400).attr('height', 36)
    .attr('rx', 6).attr('fill', '#f0fdf4').attr('stroke', '#16a34a').attr('stroke-width', 1);
  lbl(cBox as Sel, cx, y + 12, 'GroupNorm: batch-size independent (unlike BatchNorm)', { size: 8, color: '#166534', weight: '600' });
  lbl(cBox as Sel, cx, y + 26, `G=1 → LayerNorm,  G=d_model → InstanceNorm  (G=${G} here)`, { size: 8, color: '#166534' });
  y += 52;

  lbl(g, cx, y, `Params: ${fmtNum(2 * dModel)} (γ + β)  |  Works with batch size = 1  |  Used in: vision models`, { size: 10, color: '#2563eb', weight: '600' });
  y += 24;

  const steps: NormStep[] = [
    { id: 1, label: 'Reshape into G Groups', shortLabel: 'Split Groups',
      formula: `x → [b, seq, G=${G}, d/G=${groupSize}]`,
      explanation: `The feature dimension d_model=${dModel} is split into G=${G} groups of ${groupSize} features each. Normalization will be applied independently within each group.`,
      code: { title: 'Reshape', lines: [`G = ${G}`, `x = x.view(b, seq, ${G}, ${groupSize})  # split features into groups`] },
      svgGroup: 'step-norm-reshape', color: '#2e7d32', fill: '#e8f5e9' },
    { id: 2, label: 'Per-group Statistics', shortLabel: 'Group Stats',
      formula: 'μ_g = mean(x_g), σ²_g = var(x_g)',
      explanation: `For each of the G=${G} groups, compute mean and variance over the group's ${groupSize} features. Unlike BatchNorm, this is independent of batch size.`,
      code: { title: 'Group stats', lines: ['mu = x.mean(dim=-1, keepdim=True)   # per group', 'var = x.var(dim=-1, keepdim=True)    # per group'] },
      svgGroup: 'step-norm-mean', color: '#e65100', fill: '#fff3e0' },
    { id: 3, label: 'Normalize within Group', shortLabel: 'Normalize',
      formula: 'x̂_g = (x_g − μ_g) / √(σ²_g + ε)',
      explanation: `Each group is normalized independently, then reshaped back. This gives more flexibility than LayerNorm (which uses one shared mean/var for all features).`,
      code: { title: 'Normalize', lines: ['x_hat = (x - mu) / torch.sqrt(var + 1e-5)', `x_hat = x_hat.view(b, seq, ${dModel})  # reshape back`] },
      svgGroup: 'step-norm-normalize', color: '#1565c0', fill: '#e3f2fd' },
    { id: 4, label: 'Scale + Shift', shortLabel: 'γ, β',
      formula: 'out = γ ⊙ x̂ + β',
      explanation: `Apply shared learnable scale γ and shift β (each [d_model=${dModel}]). GroupNorm is batch-size independent — G=1 reduces to LayerNorm, G=d_model to InstanceNorm.`,
      code: { title: 'Scale+Shift', lines: ['out = gamma * x_hat + beta'] },
      svgGroup: 'step-norm-scale', color: '#6a1b9a', fill: '#f3e5f5' },
  ];

  return { width: W, height: y + 20, steps };
}

// ── InstanceNorm ───────────────────────────────────────────────────────────

function renderInstanceNorm(
  g: Gsel, seqLen: number, dModel: number, W: number,
): { width: number; height: number; steps: NormStep[] } {
  const cx = W / 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'InstanceNorm', `d_model=${dModel}  seq_len=${seqLen}  normalizes each feature independently`);
  y = drawNormOverviewCube(g, cx, y, 'instance');
  y += 16;

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#e0f2f1', '#00695c');
  y += 52;

  // Step 1: reshape
  const s1 = g.append('g').attr('class', 'step-node step-norm-reshape').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s1, cx, y, 360, 'View: seq as spatial, d_model as channels', `x → [batch, ${dModel}, ${seqLen}]  (channels first)`, '#e0f2f1', '#00695c', 1);
  y += 58;

  // Column-highlighted matrix showing per-feature (channel) normalization
  const matW = 220, matH = 60;
  const matX = cx - matW / 2;
  const nCols = 10, nRows = 5;
  const cw = matW / nCols, ch = matH / nRows;
  const highlightCol = 2;
  const grp1 = s1.append('g');
  for (let r = 0; r < nRows; r++) {
    for (let c = 0; c < nCols; c++) {
      const lcg = makeLcg(r * 17 + c * 31 + 5);
      const v = 0.15 + lcg() * 0.55;
      const isHighlight = c === highlightCol;
      grp1.append('rect')
        .attr('x', matX + c * cw).attr('y', y + r * ch)
        .attr('width', cw - 0.5).attr('height', ch - 0.5)
        .attr('fill', isHighlight ? d3.interpolate('#b2dfdb', '#e0f2f1')(1 - v) : d3.interpolate('#e0e0e0', '#f5f5f5')(1 - v * 0.5))
        .attr('stroke', '#e0e0e0').attr('stroke-width', 0.3);
    }
  }
  grp1.append('rect').attr('x', matX).attr('y', y).attr('width', matW).attr('height', matH)
    .attr('fill', 'none').attr('stroke', '#00695c').attr('stroke-width', 1.5).attr('rx', 3);
  // Column bracket for highlighted feature
  const bx = matX + highlightCol * cw;
  grp1.append('rect').attr('x', bx).attr('y', y).attr('width', cw).attr('height', matH)
    .attr('fill', 'none').attr('stroke', '#e65100').attr('stroke-width', 2).attr('rx', 1);
  lbl(grp1 as Sel, matX - 8, y + matH / 2, 'seq →', { size: 8, color: '#888', anchor: 'end' });
  lbl(grp1 as Sel, cx, y - 8, 'features (d_model)', { size: 8, color: '#888' });
  lbl(grp1 as Sel, bx + cw / 2, y + matH + 14, 'one feature', { size: 8, color: '#e65100', weight: '600' });
  lbl(grp1 as Sel, bx + cw / 2, y + matH + 26, '(normalizes over seq)', { size: 7, color: '#e65100' });
  y += matH + 44;

  // Step 2: per-feature stats
  const s2 = g.append('g').attr('class', 'step-node step-norm-mean').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s2, cx, y, 340, 'Per-feature μ and σ²', 'μ_c = mean_seq(x_c),  σ²_c = var_seq(x_c)', '#fff3e0', '#e65100', 2);
  y += 58;

  // Show: for one feature, stats over seq positions
  const feBox = s2.append('g');
  const feX = cx - 130;
  feBox.append('rect').attr('x', feX).attr('y', y).attr('width', 20).attr('height', 50)
    .attr('rx', 2).attr('fill', '#b2dfdb').attr('stroke', '#00695c').attr('stroke-width', 1.5);
  lbl(feBox as Sel, feX + 10, y + 25, 'feat\nc', { size: 7, color: '#00695c' });
  arrowH(feBox as Sel, feX + 28, feX + 52, y + 25, '#e65100');
  lbl(feBox as Sel, feX + 40, y + 14, 'mean/var', { size: 7, color: '#e65100', weight: '600' });
  lbl(feBox as Sel, feX + 40, y + 36, `over ${seqLen} pos`, { size: 7, color: '#888' });
  drawScalar(feBox as Sel, feX + 90, y + 8, 'μ_c', 'scalar', '#fff3e0', '#e65100');
  drawScalar(feBox as Sel, feX + 150, y + 8, 'σ²_c', 'scalar', '#fce4ec', '#c62828');
  lbl(feBox as Sel, cx + 90, y + 16, `×${dModel} features`, { size: 8, color: '#888', anchor: 'start' });
  lbl(s2, cx, y + 60, `Independent statistics per feature — no cross-feature coupling`, { size: 8, color: '#666' });
  y += 86;

  // Step 3: normalize per feature
  const s3 = g.append('g').attr('class', 'step-node step-norm-normalize').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s3, cx, y, 340, 'Normalize per feature over seq', 'x̂_c = (x_c − μ_c) / √(σ²_c + ε)', '#e3f2fd', '#1565c0', 3);
  y += 58;
  drawRowHighlight(s3, cx, y, 280, 16, '#e3f2fd', '#1565c0', 'x̂  (instance-normalized)', `[batch, ${seqLen}, ${dModel}]`, 39);
  y += 16 + 36;

  // Step 4: scale + shift + reshape back
  const s4 = g.append('g').attr('class', 'step-node step-norm-scale').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBlock(s4, cx, y, 340, 'Scale + Shift + Reshape back', 'out = γ ⊙ x̂ + β', '#f3e5f5', '#6a1b9a', 4);
  y += 58;

  const vW = 200, vH = 20;
  lbl(s4, cx - vW / 2 - 14, y + vH / 2, '×', { size: 14, weight: '700', color: '#6a1b9a' });
  drawVector(s4, cx - vW / 2, y, vW, vH, 'γ', `[d_model=${dModel}]`, '#f3e5f5', '#6a1b9a', 61);
  y += vH + 38;
  lbl(s4, cx - vW / 2 - 14, y + vH / 2, '+', { size: 14, weight: '700', color: '#ad1457' });
  drawVector(s4, cx - vW / 2, y, vW, vH, 'β', `[d_model=${dModel}]`, '#fce4ec', '#ad1457', 63);
  y += vH + 38;
  arrowDown(g, cx, y - 10, y + 2);
  drawTensor(s4 as Sel, cx - 110, y + 4, 220, 30, `out: [batch, ${seqLen}, ${dModel}]`, '#f3e5f5', '#6a1b9a');
  y += 52;

  // Comparison
  const cBox = g.append('g');
  cBox.append('rect').attr('x', cx - 200).attr('y', y).attr('width', 400).attr('height', 36)
    .attr('rx', 6).attr('fill', '#f0fdf4').attr('stroke', '#16a34a').attr('stroke-width', 1);
  lbl(cBox as Sel, cx, y + 12, 'InstanceNorm = GroupNorm with G = d_model (one group per feature)', { size: 8, color: '#166534', weight: '600' });
  lbl(cBox as Sel, cx, y + 26, 'Common in style transfer / image gen; rare in pure NLP', { size: 8, color: '#166534' });
  y += 52;

  lbl(g, cx, y, `Params: ${fmtNum(2 * dModel)} (γ + β)  |  Batch-size independent  |  Normalizes over seq_len positions`, { size: 10, color: '#2563eb', weight: '600' });
  y += 24;

  const steps: NormStep[] = [
    { id: 1, label: 'Reshape (channels first)', shortLabel: 'Reshape',
      formula: `x → [batch, ${dModel}, ${seqLen}]`,
      explanation: `Treat seq_len as the "spatial" dimension and d_model as "channels". Each of the ${dModel} features is an independent channel to be normalized over its seq_len values.`,
      code: { title: 'Reshape', lines: [`x = x.permute(0, 2, 1)  # [batch, ${dModel}, ${seqLen}]`] },
      svgGroup: 'step-norm-reshape', color: '#00695c', fill: '#e0f2f1' },
    { id: 2, label: 'Per-feature Statistics', shortLabel: 'Feature Stats',
      formula: 'μ_c = mean_seq(x_c), σ²_c = var_seq(x_c)',
      explanation: `For each of the ${dModel} feature channels, compute mean and variance over the ${seqLen} sequence positions. Each feature normalizes entirely independently.`,
      code: { title: 'Stats', lines: [`# x: [batch, ${dModel}, ${seqLen}]`, 'mu = x.mean(dim=-1, keepdim=True)', 'var = x.var(dim=-1, keepdim=True)'] },
      svgGroup: 'step-norm-mean', color: '#e65100', fill: '#fff3e0' },
    { id: 3, label: 'Normalize per Feature', shortLabel: 'Normalize',
      formula: 'x̂_c = (x_c − μ_c) / √(σ²_c + ε)',
      explanation: `Each feature channel is normalized independently. This removes per-feature scale variation while preserving cross-feature structure within each sample.`,
      code: { title: 'Normalize', lines: ['x_hat = (x - mu) / torch.sqrt(var + 1e-5)'] },
      svgGroup: 'step-norm-normalize', color: '#1565c0', fill: '#e3f2fd' },
    { id: 4, label: 'Scale + Shift', shortLabel: 'γ, β',
      formula: 'out = γ ⊙ x̂ + β',
      explanation: `Learnable γ and β restore expressiveness. InstanceNorm is equivalent to GroupNorm with G=d_model. Common in image generation (style transfer) but rarely used in pure language models.`,
      code: { title: 'Scale+Shift', lines: ['out = gamma * x_hat + beta', `out = out.permute(0, 2, 1)  # [batch, ${seqLen}, ${dModel}]`] },
      svgGroup: 'step-norm-scale', color: '#6a1b9a', fill: '#f3e5f5' },
  ];

  return { width: W, height: y + 20, steps };
}

// ── Main Entry ─────────────────────────────────────────────────────────────

export function renderNormDetailed(
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph,
): { width: number; height: number; steps: NormStep[] } {
  const variant = String(params.variant ?? 'layernorm');
  const seqLen = Number(params.seq_len ?? 128);
  const dModel = Number(params.d_model ?? 512);
  const W = 760;

  const gg = g as unknown as Gsel;

  switch (variant) {
    case 'rmsnorm':
      return renderRMSNorm(gg, seqLen, dModel, W);
    case 'batchnorm':
      return renderBatchNorm(gg, seqLen, dModel, W);
    case 'groupnorm':
      return renderGroupNorm(gg, seqLen, dModel, W);
    case 'instancenorm':
      return renderInstanceNorm(gg, seqLen, dModel, W);
    default:
      return renderLayerNorm(gg, seqLen, dModel, W);
  }
}
